describe('Table Sorting Functionality', () => {
    beforeEach(() => {
        cy.visit('/table-page'); // Replace with the actual URL of the page containing the table
    });

    it('should sort the table by the first column when the header is clicked', () => {
        cy.get('th').contains('First Column').click(); // Replace with the actual header text
        cy.get('tbody tr').then(rows => {
            const sortedRows = [...rows].sort((a, b) => {
                return Cypress.$(a).find('td').first().text().localeCompare(Cypress.$(b).find('td').first().text());
            });
            expect(rows).to.deep.equal(sortedRows);
        });
    });

    it('should not change the order of the table when clicking the same header twice', () => {
        cy.get('th').contains('First Column').click(); // First click to sort
        const initialOrder = [];
        cy.get('tbody tr').each(row => {
            initialOrder.push(row.text());
        });

        cy.get('th').contains('First Column').click(); // Second click to sort again
        const newOrder = [];
        cy.get('tbody tr').each(row => {
            newOrder.push(row.text());
        });

        expect(initialOrder).to.deep.equal(newOrder);
    });
});
